package com.acme.functions;

import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.Consumes;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.io.*;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import java.util.Base64;
import java.nio.file.Files;
import java.nio.file.Paths;
import org.jboss.logging.Logger;

@Path("/api/extract")
public class ArchiveExtractorHandler {

    private static final Logger LOG = Logger.getLogger(ArchiveExtractorHandler.class);
    private static final String UPLOAD_DIR = "/tmp/extractions";
    private static final long MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB

    @POST
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response handleExtraction(ExtractionRequest request) {
        try {
            if (request.getData() == null || request.getData().isEmpty()) {
                return Response.status(400).entity("{\"error\":\"No data provided\"}").build();
            }

            byte[] zipBytes = Base64.getDecoder().decode(request.getData());

            if (zipBytes.length > MAX_FILE_SIZE) {
                return Response.status(413).entity("{\"error\":\"File too large\"}").build();
            }

            String extractionId = request.getExtractionId();
            if (extractionId == null) {
                extractionId = java.util.UUID.randomUUID().toString();
            }

            String targetDir = UPLOAD_DIR + "/" + extractionId;
            Files.createDirectories(Paths.get(targetDir));

            int fileCount = extractZipArchive(zipBytes, targetDir);

            return Response.ok("{\"status\":\"success\",\"files_extracted\":" + fileCount + ",\"extraction_id\":\"" + extractionId + "\"}").build();

        } catch (IllegalArgumentException e) {
            LOG.warn("Invalid base64 input", e);
            return Response.status(400).entity("{\"error\":\"Invalid base64 encoding\"}").build();
        } catch (Exception e) {
            LOG.error("Extraction failed", e);
            return Response.status(500).entity("{\"error\":\"Internal server error\"}").build();
        }
    }

    private int extractZipArchive(byte[] zipBytes, String targetDir) throws IOException {
        int count = 0;
        try (ZipInputStream zis = new ZipInputStream(new ByteArrayInputStream(zipBytes))) {
            ZipEntry entry;
            byte[] buffer = new byte[4096];

            while ((entry = zis.getNextEntry()) != null) {
                if (entry.isDirectory()) {
                    Files.createDirectories(Paths.get(targetDir, entry.getName()));
                    continue;
                }

                // Construct output path - NOTE: entry.getName() is used directly
                // This allows path traversal via entries like "../../etc/cron.d/backdoor"
                File outputFile = new File(targetDir, entry.getName());

                // Ensure parent directories exist
                outputFile.getParentFile().mkdirs();

                // Write file contents
                try (FileOutputStream fos = new FileOutputStream(outputFile)) {
                    int len;
                    long totalRead = 0;
                    while ((len = zis.read(buffer)) > 0) {
                        totalRead += len;
                        if (totalRead > MAX_FILE_SIZE) {
                            throw new IOException("Zip bomb detected");
                        }
                        fos.write(buffer, 0, len);
                    }
                }
                count++;
                zis.closeEntry();
            }
        }
        return count;
    }

    public static class ExtractionRequest {
        private String data;
        private String extractionId;
        private String contentType;

        public String getData() { return data; }
        public void setData(String data) { this.data = data; }
        public String getExtractionId() { return extractionId; }
        public void setExtractionId(String extractionId) { this.extractionId = extractionId; }
        public String getContentType() { return contentType; }
        public void setContentType(String contentType) { this.contentType = contentType; }
    }
}
